DECLARE @ExceptionCount  INT            = ISNULL(@{activity('Lookup_Exception_Rate').output.firstRow.ExceptionCount}, 0);
DECLARE @CriticalCount   INT            = ISNULL(@{activity('Lookup_Exception_Rate').output.firstRow.CriticalCount}, 0);
DECLARE @RawCount        INT            = ISNULL(@{activity('Lookup_Exception_Rate').output.firstRow.RawCount}, 0);
DECLARE @MaxRate         DECIMAL(10,2)  = ISNULL(@{activity('Lookup_Exception_Rate').output.firstRow.MaxExceptionRate}, 0);
DECLARE @TotalLostRev    DECIMAL(18,2)  = ISNULL(@{activity('Lookup_Exception_Rate').output.firstRow.TotalLostRevenue}, 0);
DECLARE @Threshold       DECIMAL(10,2)  = 70.00;
DECLARE @Breached        BIT            = CASE WHEN @MaxRate > @Threshold OR @CriticalCount > 0 THEN 1 ELSE 0 END;

-- Log the check result regardless of pass/fail
INSERT INTO dbo.dq_validation_results
(PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES (
    '@{pipeline().Pipeline}',
    '@{pipeline().RunId}',
    'gold_ev_exception_summary',
    'Exception Rate <= 70% AND Zero Critical Faults',
    CASE WHEN @Breached = 0 THEN 'Passed' ELSE 'Failed' END,
    @ExceptionCount,
    GETUTCDATE()
);
